add_filter( 'user_has_cap', 'perfectpixel_pay_for_order_without_login', 20, 3 );
add_filter( 'woocommerce_order_email_verification_required', 'perfectpixel_pay_for_order_no_email_check', 20, 2 );

function perfectpixel_order_key_matches( $order_id ) {
	$order = wc_get_order( $order_id );
	$key   = isset( $_GET['key'] ) ? wc_clean( wp_unslash( $_GET['key'] ) ) : '';
	return $order && '' !== $key && hash_equals( $order->get_order_key(), $key );
}

function perfectpixel_pay_for_order_without_login( $allcaps, $caps, $args ) {
	if ( isset( $args[0], $args[2] ) && 'pay_for_order' === $args[0] && ! is_user_logged_in() && perfectpixel_order_key_matches( (int) $args[2] ) ) {
		$allcaps['pay_for_order'] = true;
	}
	return $allcaps;
}

function perfectpixel_pay_for_order_no_email_check( $required, $order ) {
	return ( $order && perfectpixel_order_key_matches( $order->get_id() ) ) ? false : $required;
}
